     Q('لماذا «أعدل» لا «أكرم» بحسب أسماء، زيادةً على ما قالته هند؟', ['للوزن', 'لأنّ ذمّ «أكرم» بخل يُغفر للأمراء، وذمّ «أعدل» ظلم لا يُغفر للحاكم، ولأنّ العدل صفة الحاكم لا الصديق فهو أوّل إعلان للرحيل', 'لأنّ أكرم ليست في المعجم', 'لأنّ سيف الدولة كان قاضيًا'], 1),
